package com.photospace.inquiries;

import com.photospace.inquiries.SubmissionSource.Utm;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import java.util.Map;

/**
 * A visitor's submission. {@code answers} maps question IDs to answers. {@code idempotencyKey} is generated by
 * the page once per form fill, so a retried or double submit is stored once. {@code website} is the hidden
 * honeypot field, which people leave empty, and {@code elapsedMillis} is how long the form was open. Anything
 * else in the body, such as a workspace or form ID, is ignored.
 */
record SubmissionRequest(
        @NotNull @Pattern(regexp = "[A-Za-z0-9-]{16,64}") String idempotencyKey,
        Map<String, String> answers,
        String service,
        InquirySource source,
        String referrer,
        Utm utm,
        String website,
        Long elapsedMillis) {}
